input.content:
locals {
  grafana_monitoring_projects = terraform.workspace == "sec" ? {
    qa      = "qa-apps-454414"
    staging = "stg-apps-454414"
    prod    = "prod-apps-454414"
    sec     = "security-454414"
    sha     = "shared-016"
    bi      = "liftit-bi"
    maps    = "liftit-production"
  } : {}
}

resource "google_service_account" "grafana_monitoring" {
  count        = terraform.workspace == "sec" ? 1 : 0
  project      = local.project_id["sec"]
  account_id   = "grafana-monitoring"
  display_name = "Grafana Cloud Monitoring Datasource"
  description  = "Read-only SA used by Grafana at observability.liftit.co to query GCP Cloud Monitoring cross-project"
}

resource "google_service_account_key" "grafana_monitoring" {
  count              = terraform.workspace == "sec" ? 1 : 0
  service_account_id = google_service_account.grafana_monitoring[0].name
  public_key_type    = "TYPE_X509_PEM_FILE"
}

resource "google_project_iam_member" "grafana_monitoring_viewer" {
  for_each = local.grafana_monitoring_projects
  project  = each.value
  role     = "roles/monitoring.viewer"
  member   = "serviceAccount:${google_service_account.grafana_monitoring[0].email}"
}

output "grafana_monitoring_sa_email" {
  value       = terraform.workspace == "sec" ? google_service_account.grafana_monitoring[0].email : null
  description = "Email de la SA grafana-monitoring (solo poblado en workspace sec)"
}

output "grafana_monitoring_sa_key" {
  value       = terraform.workspace == "sec" ? base64decode(google_service_account_key.grafana_monitoring[0].private_key) : null
  sensitive   = true
  description = "JSON key de la SA grafana-monitoring para consumo por sec/grafana-config (solo poblado en workspace sec)"
}

