      {
        "builtIn": 1,
        "datasource": {"type": "grafana", "uid": "-- Grafana --"},
        "enable": true,
        "hide": true,
        "iconColor": "rgba(0, 211, 255, 1)",
        "name": "Annotations & Alerts",
        "type": "dashboard"
      }
    ]
  },
  "description": "GKE workload observability via PromQL over Google Managed Prometheus (GMP). Uses KSM metrics enabled in Phase 6. Each row groups metrics per Deployment.",
  "editable": false,
  "fiscalYearStartMonth": 0,
  "graphTooltip": 1,
  "id": null,
  "links": [],
  "liveNow": false,
  "panels": [
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "thresholds"},
          "mappings": [],
          "thresholds": {
            "mode": "absolute",
            "steps": [
              {"color": "red", "value": null},
              {"color": "yellow", "value": 0.8},
              {"color": "green", "value": 0.95}
            ]
          },
          "unit": "percentunit"
        }
      },
      "gridPos": {"h": 4, "w": 6, "x": 0, "y": 0},
      "id": 1,
      "options": {
        "colorMode": "background",
        "graphMode": "none",
        "justifyMode": "auto",
        "orientation": "auto",
        "reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": false},
        "textMode": "auto"
      },
      "targets": [
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "A",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum(kube_deployment_status_replicas_available{cluster=\"$cluster_name\"}) / sum(kube_deployment_spec_replicas{cluster=\"$cluster_name\"})",
            "step": "60s"
          }
        }
      ],
      "title": "Deployments Healthy %",
      "type": "stat"
    },
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "thresholds"},
          "mappings": [],
          "thresholds": {
            "mode": "absolute",
            "steps": [{"color": "green", "value": null}, {"color": "red", "value": 1}]
          },
          "unit": "short"
        }
      },
      "gridPos": {"h": 4, "w": 6, "x": 6, "y": 0},
      "id": 2,
      "options": {
        "colorMode": "background",
        "graphMode": "area",
        "justifyMode": "auto",
        "orientation": "auto",
        "reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": false},
        "textMode": "auto"
      },
      "targets": [
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "A",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "count(sum by (namespace, deployment) (kube_deployment_status_replicas_unavailable{cluster=\"$cluster_name\"}) > 0)",
            "step": "60s"
          }
        }
      ],
      "title": "Deployments with Unavailable Replicas",
      "type": "stat"
    },
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "thresholds"},
          "thresholds": {"mode": "absolute", "steps": [{"color": "green", "value": null}, {"color": "red", "value": 1}]},
          "unit": "short"
        }
      },
      "gridPos": {"h": 4, "w": 6, "x": 12, "y": 0},
      "id": 3,
      "options": {
        "colorMode": "background",
        "graphMode": "area",
        "justifyMode": "auto",
        "orientation": "auto",
        "reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": false},
        "textMode": "auto"
      },
      "targets": [
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "A",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum(increase(kube_pod_container_status_restarts_total{cluster=\"$cluster_name\"}[1h]))",
            "step": "60s"
          }
        }
      ],
      "title": "Pod Restarts (last 1h)",
      "type": "stat"
    },
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "thresholds"},
          "thresholds": {"mode": "absolute", "steps": [{"color": "green", "value": null}, {"color": "yellow", "value": 0.7}, {"color": "red", "value": 0.9}]},
          "unit": "percentunit"
        }
      },
      "gridPos": {"h": 4, "w": 6, "x": 18, "y": 0},
      "id": 4,
      "options": {
        "colorMode": "background",
        "graphMode": "none",
        "justifyMode": "auto",
        "orientation": "auto",
        "reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": false},
        "textMode": "auto"
      },
      "targets": [
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "A",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "max(sum by (node) (rate(node_cpu_usage_seconds_total{cluster=\"$cluster_name\"}[5m])) / sum by (node) (machine_cpu_cores{cluster=\"$cluster_name\"}))",
            "step": "60s"
          }
        }
      ],
      "title": "Max Node CPU %",
      "type": "stat"
    },
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "thresholds"},
          "custom": {
            "align": "auto",
            "cellOptions": {"type": "auto"},
            "inspect": false
          },
          "mappings": [],
          "thresholds": {"mode": "absolute", "steps": [{"color": "green", "value": null}]}
        },
        "overrides": [
          {
            "matcher": {"id": "byName", "options": "Restarts (1h)"},
            "properties": [
              {"id": "custom.cellOptions", "value": {"type": "color-background"}},
              {"id": "thresholds", "value": {"mode": "absolute", "steps": [{"color": "green"}, {"color": "yellow", "value": 1}, {"color": "red", "value": 5}]}}
            ]
          },
          {
            "matcher": {"id": "byName", "options": "Unavailable"},
            "properties": [
              {"id": "custom.cellOptions", "value": {"type": "color-background"}},
              {"id": "thresholds", "value": {"mode": "absolute", "steps": [{"color": "green"}, {"color": "red", "value": 1}]}}
            ]
          },
          {
            "matcher": {"id": "byName", "options": "CPU (cores)"},
            "properties": [{"id": "unit", "value": "short"}, {"id": "decimals", "value": 2}]
          },
          {
            "matcher": {"id": "byName", "options": "Memory"},
            "properties": [{"id": "unit", "value": "bytes"}]
          }
        ]
      },
      "gridPos": {"h": 14, "w": 24, "x": 0, "y": 4},
      "id": 5,
      "options": {
        "cellHeight": "sm",
        "footer": {"countRows": false, "fields": "", "reducer": ["sum"], "show": false},
        "showHeader": true,
        "sortBy": [{"desc": true, "displayName": "Restarts (1h)"}]
      },
      "pluginVersion": "10.0.0",
      "targets": [
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "replicas_desired",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum by (namespace, deployment) (kube_deployment_spec_replicas{cluster=\"$cluster_name\"})",
            "format": "table",
            "instant": true,
            "step": "60s"
          }
        },
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "replicas_available",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum by (namespace, deployment) (kube_deployment_status_replicas_available{cluster=\"$cluster_name\"})",
            "format": "table",
            "instant": true,
            "step": "60s"
          }
        },
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "replicas_unavailable",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum by (namespace, deployment) (kube_deployment_status_replicas_unavailable{cluster=\"$cluster_name\"})",
            "format": "table",
            "instant": true,
            "step": "60s"
          }
        },
        {
          "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
          "queryType": "promQL",
          "refId": "restarts_1h",
          "promQLQuery": {
            "projectName": "$project",
            "expr": "sum by (namespace, deployment) (label_replace(increase(kube_pod_container_status_restarts_total{cluster=\"$cluster_name\"}[1h]), \"deployment\", \"$1\", \"pod\", \"(.+)-[a-z0-9]+-[a-z0-9]+\"))",
            "format": "table",
            "instant": true,
            "step": "60s"
          }
        }
      ],
      "title": "Deployments — Status por Workload",
      "transformations": [
        {
          "id": "joinByField",
          "options": {"byField": "deployment", "mode": "outer"}
        },
        {
          "id": "organize",
          "options": {
            "excludeByName": {"Time 1": true, "Time 2": true, "Time 3": true, "Time 4": true, "namespace 2": true, "namespace 3": true, "namespace 4": true},
            "indexByName": {},
            "renameByName": {
              "namespace 1": "Namespace",
              "deployment": "Deployment",
              "Value #replicas_desired": "Desired",
              "Value #replicas_available": "Available",
              "Value #replicas_unavailable": "Unavailable",
              "Value #restarts_1h": "Restarts (1h)"
            }
          }
        }
      ],
      "type": "table"
    },
    {
      "datasource": {"type": "stackdriver", "uid": "${datasource_uid}"},
      "fieldConfig": {
        "defaults": {
          "color": {"mode": "palette-classic"},
          "custom": {
            "drawStyle": "line",
            "fillOpacity": 10,
            "lineInterpolation": "linear",
            "lineWidth": 1,
            "pointSize": 5,
            "showPoints": "never",
            "stacking": {"group": "A", "mode": "none"}
          },
